.venv/bin/python -c "import glob,yaml; L=yaml.SafeLoader
class D(L): pass
def c(l,n,deep=False):
 m={}; d=[]
 for k,v in n.value:
  key=l.construct_object(k,deep=deep)
  if key in m: d.append(key)
  m[key]=l.construct_object(v,deep=deep)
 if d: raise ValueError('DUP '+str(d))
 return m
D.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,c)
ok=0
for f in sorted(glob.glob('.github/workflows/*.yml')):
 yaml.load(open(f),Loader=L); yaml.load(open(f),Loader=D); ok+=1
print('parsed clean, no duplicate keys:',ok)"
